        return "INVALID"

    t = " ".join(s.strip().split())
    if not t:
        return "INVALID"

    m = _YMD_NUM.fullmatch(t)
    if m:
        return _to_iso(int(m.group(1)), int(m.group(3)), int(m.group(4)))

    m = _COMPACT.fullmatch(t)
    if m:
        return _to_iso(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    m = _DMY_NUM.fullmatch(t)
    if m:
        return _to_iso(int(m.group(4)), int(m.group(3)), int(m.group(1)))

    m = _DAY_MON_YEAR.fullmatch(t)
    if m:
        month = _month_number(m.group(2))
        if month is None:
            return "INVALID"
        return _to_iso(int(m.group(3)), month, int(m.group(1)))

    m = _MON_DAY_YEAR.fullmatch(t)
    if m:
        month = _month_number(m.group(1))
        if month is None:
            return "INVALID"
        return _to_iso(int(m.group(3)), month, int(m.group(2)))

    return "INVALID"

import re
from datetime import date

INVALID = "INVALID"

_MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

_WEEKDAYS = (
    r"(?:mon(?:day)?|tue(?:s|sday)?|wed(?:nesday)?|thu(?:r|rs|rsday)?|"
    r"fri(?:day)?|sat(?:urday)?|sun(?:day)?)"
)
# Optional leading weekday, e.g. "Tuesday, " or "Tue. "
_WD_PREFIX = r"(?:" + _WEEKDAYS + r"\.?,?\s+)?"

_MON = r"([A-Za-z]{3,9})\.?"
_ORD = r"(?:st|nd|rd|th)?"


def _iso(y: int, m: int, d: int) -> str:
    """Return ISO date string if (y, m, d) is a real calendar date, else INVALID."""
    try:
        return date(y, m, d).isoformat()
    except (ValueError, OverflowError):
        return INVALID


def _month_number(name: str):
    return _MONTHS.get(name.lower().rstrip("."))


def _strip_weekday(t: str) -> str:
    """Remove a leading weekday name (e.g. 'Tuesday, ') if present."""
    return re.sub(r"^" + _WD_PREFIX, "", t, count=1, flags=re.IGNORECASE)


def parse(s: str) -> str:
    if not isinstance(s, str):
        return INVALID

    t = re.sub(r"\s+", " ", s.strip())
    if not t:
        return INVALID

    # Drop an optional leading weekday; it carries no date information.
    t = _strip_weekday(t)
    if not t:
        return INVALID

    # 1) ISO-like with year first: YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD
    m = re.fullmatch(r"(\d{4})([-/.])(\d{1,2})\2(\d{1,2})", t)
    if m:
        return _iso(int(m.group(1)), int(m.group(3)), int(m.group(4)))

    # 2) Compact: YYYYMMDD
    m = re.fullmatch(r"(\d{4})(\d{2})(\d{2})", t)
    if m:
        return _iso(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    # 3) Numeric with year last: 'a?b?YYYY' using / - or . separators.
    #    Day-first by default (DD/MM/YYYY). Only read as MM/DD when the
    #    second field cannot be a month (>12).
    m = re.fullmatch(r"(\d{1,2})([-/.])(\d{1,2})\2(\d{4})", t)
    if m:
        a, b, y = int(m.group(1)), int(m.group(3)), int(m.group(4))
        if b > 12 and a <= 12:
            mo, d = a, b          # MM/DD/YYYY
        else:
            mo, d = b, a          # DD/MM/YYYY (default)
        return _iso(y, mo, d)

    # 4) Month name first: 'March 5, 2021', 'Mar. 5 2021', 'March 5th, 2021'
    m = re.fullmatch(_MON + r"\s+(\d{1,2})" + _ORD + r",?\s+(\d{4})", t)
    if m:
        mo = _month_number(m.group(1))
        if mo is None:
            return INVALID
        return _iso(int(m.group(3)), mo, int(m.group(2)))

    # 5) Day first: '5 March 2021', '5th of March, 2021', '5-Mar-2021'
    m = re.fullmatch(
        r"(\d{1,2})" + _ORD + r"[\s-]+(?:of[\s-]+)?" + _MON + r"[\s,-]+(\d{4})",
        t,
    )
    if m:
        mo = _month_number(m.group(2))
        if mo is None:
            return INVALID
        return _iso(int(m.group(3)), mo, int(m.group(1)))

    return INVALID

import re
from datetime import date

_MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

# Optional leading weekday, e.g. "Tue, ", "Tuesday ", "Thurs. "
_WEEKDAY_PREFIX = re.compile(
    r"^(?:mon|tues?|wed|thu(?:rs?)?|fri|sat|sun)(?:day)?\.?,?\s+",
    re.IGNORECASE,
)

_SEP = r"[\s\-/.,]+"
_ORD = r"(?:st|nd|rd|th)?"

# YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD (1-2 digit month/day allowed)
_ISO = re.compile(r"(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})")

# DD/MM/YYYY (day-first, per observed examples)
_DMY_NUM = re.compile(r"(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})")

# 31 Nov 2022, 31st November, 2022, 31-Nov-2022
_DAY_MON_YEAR = re.compile(
    rf"(\d{{1,2}}){_ORD}{_SEP}([a-z]+)\.?{_SEP}(\d{{4}})",
    re.IGNORECASE,
)

# Nov 31 2022, November 31st, 2022, Nov. 31, 2022
_MON_DAY_YEAR = re.compile(
    rf"([a-z]+)\.?{_SEP}(\d{{1,2}}){_ORD}{_SEP}(\d{{4}})",
    re.IGNORECASE,
)


def _build(year: int, month: int, day: int) -> str:
    """Validate against the real calendar and format as ISO."""
    try:
        return date(year, month, day).isoformat()
    except ValueError:
        return "INVALID"


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    # Normalize whitespace and drop a leading weekday name.
    t = " ".join(s.split())
    t = _WEEKDAY_PREFIX.sub("", t, count=1).strip()
    if not t:
        return "INVALID"

    m = _ISO.fullmatch(t)
    if m:
        return _build(int(m[1]), int(m[2]), int(m[3]))

    m = _DMY_NUM.fullmatch(t)
    if m:
        return _build(int(m[3]), int(m[2]), int(m[1]))

    m = _DAY_MON_YEAR.fullmatch(t)
    if m:
        month = _MONTHS.get(m[2].lower())
        if month is None:
            return "INVALID"
        return _build(int(m[3]), month, int(m[1]))

    m = _MON_DAY_YEAR.fullmatch(t)
    if m:
        month = _MONTHS.get(m[1].lower())
        if month is None:
            return "INVALID"
        return _build(int(m[3]), month, int(m[2]))

    return "INVALID"

import re
from datetime import date

_MONTH_NAMES = [
    "january", "february", "march", "april", "may", "june",
    "july", "august", "september", "october", "november", "december",
]
_MONTHS = {}
for _i, _name in enumerate(_MONTH_NAMES, 1):
    _MONTHS[_name] = _i
    _MONTHS[_name[:3]] = _i
_MONTHS["sept"] = 9

_WEEKDAY_RE = re.compile(
    r"^(monday|tuesday|wednesday|thursday|friday|saturday|sunday|"
    r"mon|tues|tue|wed|thurs|thur|thu|fri|sat|sun)\.?\s+",
    re.IGNORECASE,
)


def _iso(year: int, month: int, day: int):
    """Return ISO date string if the date exists, else None."""
    try:
        return date(year, month, day).isoformat()
    except (ValueError, OverflowError):
        return None


def _numeric(a: str, sep: str, b: str, year: int):
    """Resolve an ambiguous numeric pair (a, b) with a given year."""
    x, y = int(a), int(b)
    if x > 12 and y <= 12:
        day, month = x, y
    elif y > 12 and x <= 12:
        month, day = x, y
    elif sep == "/":
        month, day = x, y  # assumed US convention: MM/DD/YYYY
    else:
        day, month = x, y  # assumed day-first for '-', '.', ' '
    return _iso(year, month, day)


def _named_month(word: str):
    return _MONTHS.get(word.lower().rstrip("."))


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    t = re.sub(r"\s+", " ", s).strip()
    if not t:
        return "INVALID"

    # Drop commas, optional leading weekday, and ordinal suffixes.
    t = t.replace(",", " ")
    t = re.sub(r"\s+", " ", t).strip()
    t = _WEEKDAY_RE.sub("", t, count=1)
    t = re.sub(r"\b(\d{1,2})(st|nd|rd|th)\b", r"\1", t, flags=re.IGNORECASE)
    t = t.strip()

    result = None

    # Textual month forms: "5 March 2024", "March 5 2024", "5-Mar-2024".
    if re.search(r"[A-Za-z]", t):
        t2 = re.sub(r"[-/.]", " ", t)
        t2 = re.sub(r"\s+", " ", t2).strip()

        m = re.fullmatch(r"(\d{1,2}) ([A-Za-z]+\.?) (\d{4})", t2)
        if m:
            month = _named_month(m.group(2))
            if month:
                result = _iso(int(m.group(3)), month, int(m.group(1)))
        else:
            m = re.fullmatch(r"([A-Za-z]+\.?) (\d{1,2}) (\d{4})", t2)
            if m:
                month = _named_month(m.group(1))
                if month:
                    result = _iso(int(m.group(3)), month, int(m.group(2)))

        return result if result else "INVALID"

    # ISO-like: YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD, YYYY MM DD.
    m = re.fullmatch(r"(\d{4})([-/. ])(\d{1,2})\2(\d{1,2})", t)
    if m:
        result = _iso(int(m.group(1)), int(m.group(3)), int(m.group(4)))
        return result if result else "INVALID"

    # Compact: YYYYMMDD.
    m = re.fullmatch(r"(\d{4})(\d{2})(\d{2})", t)
    if m:
        result = _iso(int(m.group(1)), int(m.group(2)), int(m.group(3)))
        return result if result else "INVALID"

    # Numeric with year last: MM/DD/YYYY or DD-MM-YYYY (see _numeric).
    m = re.fullmatch(r"(\d{1,2})([-/. ])(\d{1,2})\2(\d{4})", t)
    if m:
        result = _numeric(m.group(1), m.group(2), m.group(3), int(m.group(4)))
        return result if result else "INVALID"

    return "INVALID"

import re
from datetime import date

_MONTHS = {}
for _i, _name in enumerate(
    ["january", "february", "march", "april", "may", "june",
     "july", "august", "september", "october", "november", "december"],
    start=1,
):
    _MONTHS[_name] = _i
    _MONTHS[_name[:3]] = _i
_MONTHS["sept"] = 9

# Optional leading weekday, e.g. "Tuesday, ", "Tue. ", "fri "
# Stripped before date matching; it does not affect the resulting date.
_WEEKDAY_PREFIX = re.compile(
    r"^\s*(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday"
    r"|mon|tues|tue|wed|thurs|thur|thu|fri|sat|sun)\.?,?\s+",
    re.IGNORECASE,
)

# Year-first numeric dates: YYYY<sep>M[M]<sep>D[D], where <sep> is one of - / .
# The same separator must be used on both sides.
_YMD = re.compile(r"^\s*([0-9]{4})([-/.])([0-9]{1,2})\2([0-9]{1,2})\s*$")

# Day-first numeric dates: D[D]<sep>M[M]<sep>YYYY, where <sep> is one of - / .
# Day-first is the convention for ambiguous numeric dates (e.g. 05/03/2024 -> 2024-03-05).
_DMY_NUM = re.compile(r"^\s*([0-9]{1,2})([-/.])([0-9]{1,2})\2([0-9]{4})\s*$")

# Day-first textual dates: "22nd Feb 1900", "5 March, 2010", "1-Jan-2020"
_DMY_TEXT = re.compile(
    r"^\s*([0-9]{1,2})(?:st|nd|rd|th)?[\s\-/.,]+([A-Za-z]+)\.?[\s\-/.,]+([0-9]{4})\s*$",
    re.IGNORECASE,
)

# Month-first textual dates: "Feb 22nd, 1900", "June 31 2021", "February 22 1900"
_MDY_TEXT = re.compile(
    r"^\s*([A-Za-z]+)\.?\s+([0-9]{1,2})(?:st|nd|rd|th)?,?\s+([0-9]{4})\s*$",
    re.IGNORECASE,
)


def _month_number(name: str):
    return _MONTHS.get(name.lower())


def _build(year: str, month: int, day: str) -> str:
    try:
        d = date(int(year), month, int(day))
    except ValueError:
        # Month/day out of range, or Feb 29 in a non-leap year, etc.
        return "INVALID"
    return d.isoformat()


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    # Drop an optional weekday prefix before attempting date formats.
    s = _WEEKDAY_PREFIX.sub("", s, count=1)

    m = _YMD.fullmatch(s)
    if m is not None:
        year, _, month, day = m.groups()
        return _build(year, int(month), day)

    m = _DMY_NUM.fullmatch(s)
    if m is not None:
        day, _, month, year = m.groups()
        return _build(year, int(month), day)

    m = _DMY_TEXT.fullmatch(s)
    if m is not None:
        day, month_name, year = m.groups()
        month = _month_number(month_name)
        if month is None:
            return "INVALID"
        return _build(year, month, day)

    m = _MDY_TEXT.fullmatch(s)
    if m is not None:
        month_name, day, year = m.groups()
        month = _month_number(month_name)
        if month is None:
            return "INVALID"
        return _build(year, month, day)

    return "INVALID"
